package forge

import "time"

// User is who a token belongs to.
//
// Three fields, because three are read: the username names the session in the
// header and the auth view, the name qualifies it in parentheses, and the ID is
// what the dashboard counters and the role lookups are keyed on. An avatar and
// an email are available from both forges and neither is displayed.
type User struct {
	// ID addresses the user with the backend. Opaque — see the package doc.
	ID       string
	Username string
	Name     string
}

// Namespace is a container of repositories and of other namespaces: a GitLab
// group or subgroup, a GitHub organisation.
type Namespace struct {
	// ID addresses it with the backend; Path is `group/subgroup`, the form the
	// user reads and the clone URL is built from. See the package doc.
	ID   string
	Path string
	Name string

	Visibility string
	// Role is already humanised — "Owner", "Maintainer", "Member". A backend
	// returns a word, never a number: GitLab's levels (50, 40, 30…) and
	// GitHub's (`admin`, `maintain`, `push`, `triage`, `pull`) do not align one
	// to one, so a caller translating an integer would be translating GitLab's.
	// Empty means the role was not asked for, or is not known.
	Role string

	CreatedAt *time.Time
	// WebURL opens it in a browser. It comes from the forge rather than being
	// assembled from the host and the path — a self-hosted instance under a
	// path prefix would be assembled wrong.
	WebURL string
}

// Repository is one repository: a GitLab project, a GitHub repository.
type Repository struct {
	ID   string
	Path string
	Name string

	Visibility string
	// Role, humanised. See Namespace.Role.
	Role string

	CreatedAt      *time.Time
	LastActivityAt *time.Time
	WebURL         string

	// CIStatus is the last pipeline or workflow run — "success", "failed",
	// "running"… Empty when it was not asked for, when there is none, or when
	// the backend has no equivalent.
	CIStatus string

	// DeletionScheduled says the forge has already marked it for deletion and
	// only a permanent removal remains. It is always false on a backend whose
	// Shape says PermanentDelete is false, because there is no such state
	// there — a delete is immediate.
	DeletionScheduled bool
}

// Children is what one namespace directly contains.
//
// Two slices rather than one list of a sum type: the caller does different
// things with them — the explorer decorates repositories and not namespaces,
// the clone recurses into namespaces and clones repositories — and a single
// list would have every caller switch on a kind to get back here.
type Children struct {
	Namespaces   []Namespace
	Repositories []Repository
}

// BrowseOptions is what a listing may vary. Both fields cost something, which
// is why neither is implied.
//
// It covers RootNamespaces as well as Children, because the difference the
// clone needs is the same at both levels: its walk starts from a root and pays
// for no decoration anywhere. IncludeArchived is meaningless for namespaces —
// neither forge archives one — and is ignored there rather than split into a
// second type for one field.
type BrowseOptions struct {
	// IncludeArchived lists archived repositories. Browsing passes true — the
	// explorer shows what is there — and a clone passes
	// `forge.pull.include_archived`, which is what that setting means and the
	// only place it is read.
	IncludeArchived bool

	// Decorated fills Role and CIStatus on every repository returned.
	//
	// It is optional because it is expensive and because one caller genuinely
	// does not want it: on GitLab it is two extra requests *per repository*, so
	// a two-hundred-repository group costs 400 calls for a CI badge and a role
	// that a clone never looks at. The explorer asks for it, the clone's walk
	// does not.
	Decorated bool
}

// NewNamespace is a namespace to create.
type NewNamespace struct {
	Name        string
	Slug        string
	Description string
	Visibility  string
	// ParentID is the namespace it goes under, empty for a root one. A backend
	// whose Shape cannot nest that deep refuses rather than creating it at the
	// root — a namespace silently created somewhere else is worse than an
	// error, because the user goes looking for it where they asked for it.
	ParentID string
}

// NewRepository is a repository to create.
type NewRepository struct {
	Name        string
	Slug        string
	Description string
	Visibility  string
	// NamespaceID is where it goes; empty means the user's own namespace.
	NamespaceID string
}

// FileChange is one file in an initial commit.
type FileChange struct {
	Action  FileAction
	Path    string
	Content string
}

// FileAction is what an initial commit does to a file.
type FileAction string

const (
	FileCreate FileAction = "create"
	FileUpdate FileAction = "update"
	FileDelete FileAction = "delete"
)

// CloneMethod is how a repository is cloned.
type CloneMethod string

const (
	CloneHTTPS CloneMethod = "https"
	CloneSSH   CloneMethod = "ssh"
)

// DashboardStats are the dashboard's counters.
//
// Every count is a pointer, and nil means **nobody looked** — the counters come
// from five independent requests and any of them can fail on its own. A plain
// int cannot say that: today each failure leaves a zero, and the dashboard
// renders a dim `0` that is indistinguishable from "no merge requests assigned
// to you". That is D20 in five fields, and `Sensitive *bool` in the scan caches
// is the precedent for the fix — a value that says "not known" rather than a
// zero that reads as an answer.
type DashboardStats struct {
	AssignedChangeRequests *int
	ReviewChangeRequests   *int
	AssignedIssues         *int
	Repositories           *int
	Namespaces             *int
}

// Count is a small helper for a backend filling DashboardStats: it returns a
// pointer to n, so a successful request reads `stats.AssignedIssues = Count(n)`
// and a failed one leaves the field nil by doing nothing.
func Count(n int) *int { return &n }

package forge

import "github.com/anthnel/devdesk/internal/config"

// Vocabulary is what a forge is *called*, as opposed to what it can do.
//
// The distinction is §3.6's: "Group" against "Organization" is a **word**,
// while nesting depth and the visibility set are **shapes** — they change what
// the application can promise, and no wording helps with them. Shape carries
// the second; this carries the first, and neither grows conditionals for the
// other.
//
// # Per forge, not neutral
//
// A GitLab user says *group*, a GitHub user says *repository*. "Namespace" is a
// third language nobody speaks, and it makes the application read as an
// abstraction layer rather than as a tool. So every word here is the one its
// forge's own documentation uses.
//
// The field names are neutral because the *code* has to be — a view cannot
// switch on which forge it is talking to — but nothing a user reads is.
//
// # No view writes a forge's name into a string
//
// That is the rule this type exists to make checkable, and
// TestNoViewNamesAForge (internal/ui/vocabtest) walks every string literal
// under internal/ui to enforce it. A command name is not covered: it is routing
// identity, the same for both forges, and lives in internal/command.
type Vocabulary struct {
	// Name is the forge as it names itself — "GitLab", "GitHub". Capitalised:
	// it is a proper noun, and it is what titles and messages interpolate.
	Name string

	// Namespace holds repositories and, on some forges, other namespaces.
	Namespace, Namespaces string

	// Repository is one repository.
	Repository, Repositories string

	// ChangeRequest is a proposal to merge a branch.
	ChangeRequest, ChangeRequests string

	// ChangeRequestShort is the initialism — "MR", "PR". The dashboard's tree
	// nodes are eleven cells wide, so the long form does not fit and truncating
	// it would produce "Merge Req…" on one forge and "Pull Requ…" on the other.
	ChangeRequestShort string

	// TokenLabel is what the auth view calls the secret it asks for.
	TokenLabel string

	// TokenPlaceholder is an example token, shown greyed in the input until the
	// user types.
	//
	// It is a hint and never a check: DevDesk does not validate the prefix, and
	// a forge that changes its format must not turn a working token into a
	// refused one. Shaped like a real value rather than as prose, because that
	// is what a placeholder is — the prose about which prefixes exist lives in
	// TokenHelp, where there is room to name more than one.
	TokenPlaceholder string

	// TokenHelp says where to create a token and which scopes it needs. One
	// sentence, because it is rendered in a help pane beside others.
	TokenHelp string

	// ExampleURL is what the configuration view suggests as a host. The public
	// instance, because it is the only address that is the same for everyone —
	// a self-hosted example would be a hostname nobody has.
	ExampleURL string
}

// gitlabVocabulary and githubVocabulary are the two, written out rather than
// derived: every word is a decision about what that forge's users call things,
// and a rule that produced them would be a rule about English rather than about
// either product.
var (
	gitlabVocabulary = Vocabulary{
		Name:               "GitLab",
		Namespace:          "Group",
		Namespaces:         "Groups",
		Repository:         "Project",
		Repositories:       "Projects",
		ChangeRequest:      "Merge Request",
		ChangeRequests:     "Merge Requests",
		ChangeRequestShort: "MR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "glpat-…",
		TokenHelp:          "Create a token in GitLab > Settings > Access Tokens. Required scopes: api, read_user.",
		ExampleURL:         "https://gitlab.com",
	}

	githubVocabulary = Vocabulary{
		Name:               "GitHub",
		Namespace:          "Organization",
		Namespaces:         "Organizations",
		Repository:         "Repository",
		Repositories:       "Repositories",
		ChangeRequest:      "Pull Request",
		ChangeRequests:     "Pull Requests",
		ChangeRequestShort: "PR",
		TokenLabel:         "Personal Access Token",
		TokenPlaceholder:   "ghp_… or github_pat_…",
		TokenHelp:          "Create a token in GitHub > Settings > Developer settings > Personal access tokens. Required scopes: repo, read:org.",
		ExampleURL:         "https://github.com",
	}
)

// VocabularyFor resolves the wording for a configured forge type.
//
// It takes the **configured** type rather than a live Forge, and that is
// deliberate: the explorer's "not authenticated" screen and the auth view's own
// title both need the words before any session exists. A method on Forge would
// be unavailable exactly where the words are needed most.
//
// An unknown type falls back to GitLab rather than to an empty Vocabulary. A
// screen with no nouns on it is a worse failure than a screen using the wrong
// forge's nouns, and config.applyDefaults already guarantees a known value —
// this is the belt to that brace.
func VocabularyFor(forgeType string) Vocabulary {
	switch forgeType {
	case config.ForgeGitHub:
		return githubVocabulary
	default:
		return gitlabVocabulary
	}
}

package config

// The forge vocabulary. It is stated here as well as in internal/forge, and
// TestTheForgeVocabularyMatchesTheBackends keeps the two in step — the same
// arrangement the registry `provider` names have between config and
// registrymgr (§3.8). A config value that no backend answers to would resolve
// to nothing at load, which is a failure mode worth a test rather than a
// comment.
const (
	// ForgeGitLab is the default, and what every file written before `type:`
	// existed means.
	ForgeGitLab = "gitlab"
	ForgeGitHub = "github"
)

// ForgeTypes lists what `forge.type` accepts, in the order the configuration
// view cycles them.
func ForgeTypes() []string { return []string{ForgeGitLab, ForgeGitHub} }

// migrateGitLabSection carries a legacy `gitlab:` block into `forge:`.
//
// Field by field, and only where the new value is empty: a file that already
// carries `forge:` keeps it, so a half-written file does not have its new
// values overwritten by its old ones. The legacy struct is cleared once read,
// so the key leaves the file on the next save — the precedent is
// RegistryItem.AuthEnabled and, right below this in applyDefaults,
// `docker.network_tool_image`.
//
// It runs **before** the defaults. yaml.Unmarshal is not strict here, so an
// un-migrated block is dropped in silence, and the silence would point a
// context at no host at all.
func migrateGitLabSection(cfg *Config) {
	legacy := cfg.GitLab
	if legacy == (GitLabConfig{}) {
		return
	}
	defer func() {
		// A legacy file predates `type:` by definition, so it can only mean
		// GitLab. Cleared last, so the key leaves the file on the next save.
		if cfg.Forge.Type == "" {
			cfg.Forge.Type = ForgeGitLab
		}
		cfg.GitLab = GitLabConfig{}
	}()

	// Nothing under `forge:` at all — the ordinary case, and the only one where
	// a bool can be carried over safely: IncludeArchived's zero value *is*
	// false, so no per-field guard could tell "unset" from "deliberately off".
	if cfg.Forge == (ForgeConfig{}) {
		cfg.Forge = ForgeConfig{
			URL:                legacy.URL,
			DefaultParentGroup: legacy.DefaultParentGroup,
			DefaultVisibility:  legacy.DefaultVisibility,
			CloneMethod:        legacy.CloneMethod,
			Pull: ForgePullConfig{
				ParallelJobs:    legacy.Pull.ParallelJobs,
				IncludeArchived: legacy.Pull.IncludeArchived,
			},
		}
		return
	}

	// Both blocks are present, which a hand-edited file can be. The new one
	// wins field by field: its values were written later, and overwriting them
	// with the old ones would undo the edit that created the situation.
	if cfg.Forge.URL == "" {
		cfg.Forge.URL = legacy.URL
	}
	if cfg.Forge.DefaultParentGroup == "" {
		cfg.Forge.DefaultParentGroup = legacy.DefaultParentGroup
	}
	if cfg.Forge.DefaultVisibility == "" {
		cfg.Forge.DefaultVisibility = legacy.DefaultVisibility
	}
	if cfg.Forge.CloneMethod == "" {
		cfg.Forge.CloneMethod = legacy.CloneMethod
	}
	if cfg.Forge.Pull.ParallelJobs == 0 {
		cfg.Forge.Pull.ParallelJobs = legacy.Pull.ParallelJobs
	}
}

package config

// The container engine names. They are stated here as well as in
// internal/engine, and TestEveryConfiguredEngineHasAShape keeps the two in
// step — the same arrangement the forge names have (§3.6) and the registry
// `provider` names have (§3.8). config must not import a backend, and a
// backend must not be the authority on what a config file may say, so a test
// is the only thing that can hold them together.
const (
	// EngineAuto is the default: docker if it is on PATH, else podman. It
	// spares anyone who installed exactly one of the two a setting they have
	// no opinion about — app.secret_backend's precedent (§3.9).
	EngineAuto   = "auto"
	EngineDocker = "docker"
	EnginePodman = "podman"
)

// ContainerEngines lists the values app.container_engine names, in the order
// the configuration view cycles them.
//
// It is not the whole set the setting accepts: an explicit path to a binary is
// also honoured (internal/engine.Resolve), and is deliberately not cycled —
// there is nothing to cycle through. The same compromise scan.trivy_path makes.
func ContainerEngines() []string { return []string{EngineAuto, EngineDocker, EnginePodman} }

package credentials

import (
	"bytes"
	"context"
	"os/exec"
	"strings"
	"time"
)

// Backend names where a secret actually ends up.
type Backend string

const (
	// BackendKeyring is the host's own secret manager. The only backend that
	// can promise the secret is not sitting in a plaintext file somewhere.
	BackendKeyring Backend = "keyring"

	// BackendGitCredential delegates to git's configured credential helper.
	// Honest only as far as that helper is: `store` writes plaintext, which is
	// why gitHelperUsable refuses it.
	BackendGitCredential Backend = "git-credential"

	// BackendMemory holds the secret for this session and nothing longer. It is
	// the fallback, and it is deliberately the worst one — see Selection.Detail.
	BackendMemory Backend = "memory"
)

// Preference values accepted from app.secret_backend in the configuration.
const (
	PreferenceAuto          = "auto"
	PreferenceKeyring       = "keyring"
	PreferenceGitCredential = "git-credential"
)

// gitConfigTimeout bounds the `git config` read that inspects the helper. Same
// reasoning as credentialTimeout: a blocked git call must not freeze the TUI.
const gitConfigTimeout = 2 * time.Second

// Selection is a storage together with the answer to "where does the secret go".
// The UI needs both: it has to tell the user which store a token was written
// to, and warn them when the answer is "nowhere that survives this session".
type Selection struct {
	Storage Storage
	Backend Backend

	// Detail is a sentence for the user, naming the store or explaining why
	// there is none. Always populated.
	Detail string
}

// Persists reports whether a secret saved here survives the process.
func (s Selection) Persists() bool {
	return s.Backend != BackendMemory
}

// Select resolves the storage for a context.
//
// The order is deliberate and there is exactly one destination — writing to
// several at once is what made the old "secure" option store the token in the
// credential manager *and* in a plaintext file (§3.9):
//
//  1. the host secret store, when one answers;
//  2. git's credential helper, when git is configured with one that does not
//     itself write plaintext;
//  3. memory, for this session only.
//
// preference comes from app.secret_backend and pins the head of that list.
// A pinned backend that turns out to be unreachable falls through to memory
// rather than silently to the other one: someone who asked for the keyring
// should not get a git helper without being told.
//
// The returned Selection must be kept for the lifetime of the context. Calling
// Select again yields a fresh MemoryStorage, and a token saved into the old one
// would be invisible to it.
func Select(contextName, preference string) Selection {
	switch preference {
	case PreferenceKeyring:
		if KeyringAvailable() {
			return keyringSelection(contextName)
		}
		return memorySelection(KeyringName() + " is configured but not reachable")

	case PreferenceGitCredential:
		if helper, ok := gitHelperUsable(); ok {
			return gitSelection(contextName, helper)
		}
		return memorySelection("git is not configured with a credential helper that stores secrets safely")
	}

	if KeyringAvailable() {
		return keyringSelection(contextName)
	}
	if helper, ok := gitHelperUsable(); ok {
		return gitSelection(contextName, helper)
	}
	return memorySelection("no " + KeyringName() + " and no usable git credential helper")
}

func keyringSelection(contextName string) Selection {
	return Selection{
		Storage: NewKeyringStorage(contextName),
		Backend: BackendKeyring,
		Detail:  "Secrets are stored in the " + KeyringName() + ".",
	}
}

func gitSelection(contextName, helper string) Selection {
	return Selection{
		Storage: NewGitCredentialStorageWithContext(contextName),
		Backend: BackendGitCredential,
		Detail:  "Secrets are stored by the git credential helper (" + helper + ").",
	}
}

// SessionOnly returns a Selection that keeps secrets in this process and
// nowhere else. Select falls back to it, and the router starts on it before it
// has resolved a real backend — a Selection is never nil, so nothing has to
// guard against a missing store.
func SessionOnly(why string) Selection {
	return Selection{
		Storage: NewMemoryStorage(),
		Backend: BackendMemory,
		Detail:  "Nothing is saved — " + why + ". You will have to authenticate again next launch.",
	}
}

func memorySelection(why string) Selection {
	return SessionOnly(why)
}

// gitHelperUsable reports whether git has a credential helper configured that
// is worth delegating to, and names it.
//
// `store` is refused by name: it keeps credentials in ~/.git-credentials in
// plaintext, which is the failure this whole change exists to remove — moving
// the token from one plaintext file to another is not a fix. An unset helper is
// refused too, since git would then have nowhere to put the secret and would
// quietly succeed at storing nothing.
//
// Every other helper is accepted. There is no list of the good ones to check
// against: `manager`, `osxkeychain`, `libsecret`, `wincred` and any number of
// third-party helpers all reach a real store, and enumerating them would only
// mean rejecting the next one someone installs.
func gitHelperUsable() (string, bool) {
	ctx, cancel := context.WithTimeout(context.Background(), gitConfigTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "config", "--get-all", "credential.helper")
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	cmd.WaitDelay = credentialWaitDelay
	if err := cmd.Run(); err != nil {
		return "", false
	}

	// git resolves the last helper that answers, so read them in that order and
	// take the first usable one from the end.
	lines := strings.Split(strings.TrimSpace(stdout.String()), "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if name, ok := usableHelperName(lines[i]); ok {
			return name, true
		}
	}
	return "", false
}

// usableHelperName extracts the helper name from one credential.helper value
// and reports whether it stores secrets somewhere other than a plaintext file.
func usableHelperName(value string) (string, bool) {
	value = strings.TrimSpace(value)
	if value == "" {
		return "", false
	}

	// A value may carry arguments (`store --file=/path`), and a leading `!`
	// marks a shell command. Only the first word names the helper.
	name := strings.TrimPrefix(strings.Fields(value)[0], "!")
	if name == "store" {
		return "", false
	}
	return name, true
}

// Package credentials stores the secrets DevDesk holds — forge tokens, registry
// passwords — in the host's secret manager, and never in a file DevDesk writes
// itself. Select resolves which backend a context gets.
package credentials

import (
	"errors"
	"fmt"
	"sync"
)

// ErrNotFound says a store holds nothing under that key. Every Load wraps it,
// and the distinction is not pedantry: a caller that cannot tell "never stored"
// from "the store would not answer" will mint a replacement over a secret that
// is still there, because a locked keyring and an empty one look the same. It
// is what internal/mcp.ResolveToken checks before generating a bearer token.
var ErrNotFound = errors.New("no credentials found")

// Storage interface for storing/retrieving credentials
type Storage interface {
	Save(url, token string) error
	Load(url string) (token string, err error)
	Delete(url string) error
}

// MemoryStorage keeps secrets for this session only. It is what Select falls
// back to when no host store answers, so it has to be worse than a file on
// purpose: a fallback that silently persists is how the old "secure" option
// came to write plaintext (§3.9).
//
// It is shared between the Cmd goroutines of every view, hence the lock.
type MemoryStorage struct {
	mu    sync.RWMutex
	creds map[string]string
}

// NewMemoryStorage creates a new MemoryStorage
func NewMemoryStorage() *MemoryStorage {
	return &MemoryStorage{
		creds: make(map[string]string),
	}
}

// Save stores a token in memory
func (m *MemoryStorage) Save(url, token string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.creds[url] = token
	return nil
}

// Load loads a token from memory
func (m *MemoryStorage) Load(url string) (string, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	token, ok := m.creds[url]
	if !ok {
		return "", fmt.Errorf("%w for %s", ErrNotFound, url)
	}
	return token, nil
}

// Delete removes a token from memory
func (m *MemoryStorage) Delete(url string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	delete(m.creds, url)
	return nil
}

