542				LogFile:         filepath.Join(homeDir, ".devdesk", "devdesk.log"),
543				DefaultView:     "dashboard",
544				WorkspacesDir:   filepath.Join(homeDir, "workspaces"),
545				IDECommand:      "code",
546				SecretBackend:   "auto",
547				ContainerEngine: EngineAuto,
548			},
549			Status: StatusConfig{
550				RefreshInterval: 10,
551				AutoRefresh:     true,
552				Timeout:         5,
553				Components:      []ComponentConfig{},
554			},
