570				GitleaksSource:     ToolSourceAuto,
571				GitleaksPath:       "", // Auto-detect in PATH
572				PlumberSource:      ToolSourceAuto,
573				PlumberPath:        "", // Auto-detect in PATH
574				CacheDir:           filepath.Join(homeDir, ".devdesk", "cache", "scans"),
575				MaxCachedReports:   50,
576				Timeout:            300, // 5 minutes
577				MaxConcurrentScans: 3,
